static bool stop(pid_t pid,int& status) {
 auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(5);
 while(std::chrono::steady_clock::now()<deadline){const auto waited=waitpid(pid,&status,__WALL|WNOHANG);if(waited==pid)return WIFSTOPPED(status);if(waited<0&&errno!=EINTR)return false;usleep(10000);}return false;
}
static int probe(const char* path,unsigned variant) {
 const bool mixed=variant!=0;
 Fixture f(path);printf("fixture %s\n",f.line().c_str());LinuxProcessHandle p(f.pid);auto host=p.targetDescription().host;const size_t page=sysconf(_SC_PAGESIZE);
 const bool compat=host.architecture==CpuArchitecture::X86_32||mixed;if(mixed&&host.architecture!=CpuArchitecture::X86_64)return 9;
 auto scratch=p.allocate(page,MemProt::All);auto storage=executeMemorySyscall(f.pid,host,MemorySyscall::Map,{0,3*page,7,0x22u|(mixed?0x40u:0u),UINT64_MAX,0});if(!scratch||!storage)return 2;
 int status=0;if(ptrace(PTRACE_SEIZE,f.pid,nullptr,nullptr)<0||ptrace(PTRACE_INTERRUPT,f.pid,nullptr,nullptr)<0||!stop(f.pid,status))return 3;
 user_regs_struct original{},r{};ptrace(PTRACE_GETREGS,f.pid,nullptr,&original);r=original;const uintptr_t edge=*storage+page-2,after=edge+2,buffer=*storage+2*page;
 const std::array<uint8_t,3> code=compat?std::array<uint8_t,3>{0xcd,0x80,0xcc}:std::array<uint8_t,3>{0x0f,0x05,0xcc};writeMemory(f.pid,edge,code.data(),3);const std::array<int64_t,2> duration64{2,0};const std::array<int32_t,2> duration32{2,0};
 if(compat)writeMemory(f.pid,buffer,duration32.data(),sizeof(duration32));else writeMemory(f.pid,buffer,duration64.data(),sizeof(duration64));
 const uint64_t nr=compat?162:35|(host.abi==TargetAbi::LinuxX32?0x40000000:0);r.rip=edge;r.orig_rax=UINT64_MAX;r.rax=nr;if(compat){r.rbx=buffer;r.rcx=0;}else{r.rdi=buffer;r.rsi=0;}
 const auto started=std::chrono::steady_clock::now();if(ptrace(PTRACE_SETREGS,f.pid,nullptr,&r)<0||ptrace(PTRACE_CONT,f.pid,nullptr,nullptr)<0)return 4;
 bool blocked=false;std::string line;for(unsigned retry=0;retry<200&&!blocked;++retry){std::ifstream in("/proc/"+std::to_string(f.pid)+"/syscall");std::getline(in,line);long long actual=-1;std::array<uint64_t,8> args{};std::istringstream s(line);s>>actual>>std::hex;for(auto&value:args)s>>value;blocked=bool(s)&&actual==nr&&args[0]==buffer&&args[7]==after;if(!blocked)usleep(10000);}printf("blocked=%d syscall=%s\n",blocked,line.c_str());if(!blocked)return 5;
 usleep(1000000);if(ptrace(PTRACE_INTERRUPT,f.pid,nullptr,nullptr)<0||!stop(f.pid,status))return 6;
 user_regs_struct parked{};ptrace(PTRACE_GETREGS,f.pid,nullptr,&parked);printf("parked pc=%llx expected=%lx rax=%llx orig=%llx cs=%llx status=%x\n",parked.rip,after,parked.rax,parked.orig_rax,parked.cs,status);
 if(variant>=2){parked.rax=static_cast<uint32_t>(parked.rax);if(ptrace(PTRACE_SETREGS,f.pid,nullptr,&parked)<0)return 11;}
 struct Info {uint8_t op,pad[3];uint32_t arch;uint64_t pc,sp;uint8_t data[64];};
 Info before{};errno=0;const auto infoBefore=ptrace(static_cast<__ptrace_request>(0x420e),f.pid,reinterpret_cast<void*>(sizeof(before)),&before);printf("entry before bytes=%ld arch=%x error=%d editedrax=%llx\n",infoBefore,before.arch,errno,parked.rax);
 auto mapped=variant==3 ? std::expected<uint64_t,TargetSyscallFailure>(uint64_t{0}) : executeStoppedMemorySyscall(f.pid,host,MemorySyscall::Map,{0,page,3,0x22,UINT64_MAX,0},*scratch);bool restored=variant==3;if(mapped&&variant!=3){auto protectedPage=executeStoppedMemorySyscall(f.pid,host,MemorySyscall::Protect,{*mapped,page,1,0,0,0},*scratch);auto freed=executeStoppedMemorySyscall(f.pid,host,MemorySyscall::Unmap,{*mapped,page,0,0,0,0},*scratch);restored=protectedPage&&freed;}Info afterInfo{};errno=0;const auto infoAfter=ptrace(static_cast<__ptrace_request>(0x420e),f.pid,reinterpret_cast<void*>(sizeof(afterInfo)),&afterInfo);printf("entry after bytes=%ld arch=%x error=%d\n",infoAfter,afterInfo.arch,errno);ptrace(PTRACE_GETREGS,f.pid,nullptr,&r);printf("memory=%d restored=%d GPexact=%d pc=%llx rax=%llx orig=%llx\n",bool(mapped),restored,!memcmp(&parked,&r,sizeof(r)),r.rip,r.rax,r.orig_rax);fflush(stdout);
 if(variant>=4){auto emulated=parked;emulated.rip=edge;emulated.rax=parked.orig_rax;emulated.orig_rax=UINT64_MAX;bool entered=ptrace(PTRACE_SETREGS,f.pid,nullptr,&emulated)==0&&ptrace(static_cast<__ptrace_request>(31),f.pid,nullptr,nullptr)==0&&stop(f.pid,status);ptrace(PTRACE_GETREGS,f.pid,nullptr,&r);Info emuInfo{};const auto emuBytes=ptrace(static_cast<__ptrace_request>(0x420e),f.pid,reinterpret_cast<void*>(sizeof(emuInfo)),&emuInfo);printf("emulated entered=%d signal=%d pc=%llx orig=%llx rax=%llx bytes=%ld arch=%x\n",entered,WSTOPSIG(status),r.rip,r.orig_rax,r.rax,emuBytes,emuInfo.arch);if(!entered)return 12;ptrace(PTRACE_SETREGS,f.pid,nullptr,&parked);if(variant==5){bool interrupted=ptrace(PTRACE_INTERRUPT,f.pid,nullptr,nullptr)==0&&ptrace(PTRACE_CONT,f.pid,nullptr,nullptr)==0&&stop(f.pid,status);ptrace(PTRACE_GETREGS,f.pid,nullptr,&r);Info stoppedInfo{};ptrace(static_cast<__ptrace_request>(0x420e),f.pid,reinterpret_cast<void*>(sizeof(stoppedInfo)),&stoppedInfo);printf("interrupt interrupted=%d status=%x arch=%x exact=%d pc=%llx rax=%llx orig=%llx\n",interrupted,status,stoppedInfo.arch,!memcmp(&parked,&r,sizeof(r)),r.rip,r.rax,r.orig_rax);}}
 usleep(500000);
 ptrace(PTRACE_CONT,f.pid,nullptr,nullptr);bool stopped=stop(f.pid,status);ptrace(PTRACE_GETREGS,f.pid,nullptr,&r);const auto elapsed=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-started).count();printf("actual stopped=%d stop=%d pc=%llx rax=%llx elapsed=%lld\n",stopped,WSTOPSIG(status),r.rip,r.rax,static_cast<long long>(elapsed));fflush(stdout);
 ptrace(PTRACE_SETREGS,f.pid,nullptr,&original);executeStoppedMemorySyscall(f.pid,host,MemorySyscall::Unmap,{*storage,3*page,0,0,0,0},*scratch);executeQuiescedMemorySyscall(f.pid,host,MemorySyscall::Unmap,{*scratch,page,0,0,0,0});ptrace(PTRACE_DETACH,f.pid,nullptr,nullptr);printf("console=%d\n",f.value());return stopped&&WSTOPSIG(status)==SIGTRAP&&r.rip==after+1&&r.rax==0&&elapsed>=1800&&elapsed<2800?0:1;
}
